11	func TestExportSplitSingleFile(t *testing.T) {
12		tmp := t.TempDir()
13		in := filepath.Join(tmp, "input.pdf")
14		outDir := filepath.Join(tmp, "out")
15		if err := os.MkdirAll(outDir, 0o755); err != nil {
16			t.Fatal(err)
17		}
18	
